package com.trampolim.api.company;
import java.util.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@RestController @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanyPassportController {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;public CompanyPassportController(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 public record Input(String token){}
 @PostMapping("/api/company/passport/verify")public Map<String,Object> verify(@AuthenticationPrincipal String email,@RequestBody Input input){var members=jdbc.queryForList("SELECT m.company_id,u.id FROM company_members m JOIN company_users u ON u.id=m.user_id WHERE LOWER(u.email)=LOWER(?) AND u.account_status='ACTIVE' AND u.email_verified=TRUE AND m.role IN ('OWNER','ADMIN','RECRUITER') ORDER BY m.company_id LIMIT 1",email);if(members.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Use uma conta empresarial verificada com permissão de recrutamento.");if(input==null||input.token()==null||!input.token().matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe o código de compartilhamento fornecido pelo aluno.");var result=bridge.convert(bridge.post("/integrations/capacita/passport/verify",Map.of("token",input.token(),"recipientEmail",email)),Map.class);jdbc.update("INSERT INTO company_audit_events(company_id,actor_user_id,event_type) VALUES (?,?,'PASSPORT_VERIFIED')",members.get(0).get("company_id"),members.get(0).get("id"));return result;}
}
